#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / "src"
OUT = ROOT / "build" / "DCH-Shure-MXCWAPT.qplug"

MODULES = [
    "commands",
    "protocol",
    "state",
    "diagnostics",
    "properties",
    "controls",
    "layout",
    "runtime",
]


def module_name(name: str) -> str:
    return f"src.modules.{name}"


def main() -> None:
    chunks = [
        "-- Generated by scripts/build_qplug.py. Edit files in src/ instead.\n",
    ]
    for mod in MODULES:
        path = SRC / "modules" / f"{mod}.lua"
        chunks.append(f"\npackage.preload[{module_name(mod)!r}] = function(...)\n")
        chunks.append(path.read_text())
        chunks.append("\nend\n")
    chunks.append("\n")
    chunks.append((SRC / "DCH-Shure-MXCWAPT.qplug.lua").read_text())
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text("".join(chunks))
    print(OUT)


if __name__ == "__main__":
    main()
